const escape = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9', agents:'M8 7V5a4 4 0 0 1 8 0v2M5 7h14v13H5zM9 12h.01M15 12h.01M9 16h6',
 wiki:'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zM14 7a3 3 0 0 1 3-3h4v15h-3a4 4 0 0 0-4 2',
 enterprise:'M3 21h18M5 21V9h6v12M11 21V3h7v18M8 12h.01M8 16h.01M14 7h.01M14 11h.01M14 15h.01',
 runs:'M3 12h4l3-8 4 16 3-8h4', experiments:'M9 3v6l-5 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-5-9V3M8 3h8M8 15h8', reviews:'M9 4H5v17h14V4h-4M9 2h6v4H9zM8 12l2 2 5-5',
 arrow:'M7 17 17 7M7 7h10v10', attach:'m8 12 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9',
 plus:'M12 5v14M5 12h14', chevron:'m9 5 7 7-7 7', file:'M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6', back:'m14 6-6 6 6 6', settings:'M4 7h16M4 17h16M8 4v6M16 14v6', layers:'m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5', info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'
};
const icon = (name,size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const nav = [['home','Home'],['agents','Agents'],['wiki','Wiki'],['enterprise','Enterprise'],['runs','Observability'],['reviews','Reviews'],['experiments','Development']];
// Real local reads. There is deliberately no demo-data fallback on failure.
const S={planningAllowance:null,testPlans:[],qualificationCheckedFor:null,qualificationChecking:false,offlineCheck:null,offlineBusy:false,workflowGuide:null,workflows:[],projectTests:[],projectTestDraft:{objective:"",max_depth:1,source_id:"",max_requests:8,max_output_tokens:4096},projectSources:[],route:'home',meta:null,csrf:null,caps:[],runs:[],docs:[],imports:[],reviews:[],run:null,result:null,events:[],source:null,graph:null,graphTier:'accepted',wikiTab:'read',wikiModel:null,wikiPage:null,wikiError:null,wikiEv:null,graphError:null,semanticCandidates:null,candidateId:null,candidateError:null,files:[],selected:[],capOpen:false,detail:false,draftMessages:[],draftSaved:false,workText:{},error:null,ready:false,sending:false,settings:null,settingsTab:'models',scope:null,scopes:null,loadedScope:null,wikiScope:null,runProducts:null,dispositions:null};
let stream=null,toastTimer,readGeneration=0,runReadGeneration=0;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
async function api(path,body){for(let attempt=0;;attempt++){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Catalyst-CSRF':S.csrf},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok){if(body===undefined&&response.status===409&&data.error?.code==='workspace_busy'&&attempt<3){await new Promise(resolve=>setTimeout(resolve,100*(2**attempt)));continue}const error=new Error(data.error?.code||`HTTP_${response.status}`);error.status=response.status;throw error}return data}}
const go=r=>{if(location.hash===`#${r}`){render();loadRoute()}else location.hash=r};
const badge=t=>`<span class="preview-label">${escape(t)}</span>`;
const note=()=>`<p class="footer-note">本机真实接入 · ${S.settings?.enabled?'DeepSeek 文本对话已开启':'文本模型未开启'} · 附件提取 MOCK · 未授权正式接纳</p>`;
const head=(t,d,a='')=>`<div class="page-heading"><div><h1>${escape(t)}</h1><p class="page-description">${escape(d)}</p></div>${a?`<div class="page-actions">${a}</div>`:''}</div>`;
const empty=(t,d)=>`<div class="empty"><h2>${escape(t)}</h2><p>${escape(d)}</p></div>`;
const statusText=s=>({LOCAL_INFO:'本机说明',CHAT_COMPLETED:'对话完成',running:'运行中',success:'执行结束',failure:'执行失败',incomplete:'未完整结束',WAITING_FOR_REVIEW:'待确认',CAPTURED_BEFORE_HARVEST:'已捕获 · 未采收',CANCELLED:'已取消',BLOCKED:'已阻断',FAILED:'执行失败'}[s]||s||'未知');
const capName=c=>({understand:'理解企业资料',wiki_search:'查询来源知识',compose_report:'整理报告',write_artifact:'保存 Markdown 交付物'}[c.id]||c.name);
function picks(){return S.selected.map(ref=>{const c=S.caps.find(c=>`${c.id}@${c.version}`===ref);return `<span class="chip">${escape(c?capName(c):ref)}<small>${escape(c?.version)}</small><button data-remove="${escape(ref)}" aria-label="移除能力">×</button></span>`}).join('')}
function bindComposerDraft(input){if(input)input.oninput=e=>{S.message=e.target.value};}
function compose(agent=false){return `<form class="composer ${agent?'drop-target':''}" id="composer"><textarea id="message-input" aria-label="${agent?'Agent 草案描述':'工作需求'}" rows="3" maxlength="20000" placeholder="${agent?'描述职责，也可以从右侧添加能力…':'描述你的工作需求，添加 TXT、MD 或 PPTX 资料…'}">${escape(S.message||'')}</textarea>${agent?`<div class="chips">${picks()}</div>`:''}<div class="chips">${S.files.map(f=>`<span class="chip">${icon('file',12)}${escape(f.name)}<button type="button" id="clear-file" aria-label="移除附件">×</button></span>`).join('')}</div><div class="composer-bottom"><button type="button" id="attach" class="attach">${icon('attach',14)}添加资料</button><input type="file" id="file-input" accept=".txt,.md,.pptx" hidden><button class="primary" type="submit" ${S.sending?'disabled':''}>${S.sending?'正在提交…':agent?'加入草案':'提出需求'}${icon('arrow',13)}</button></div></form>`}
function runRows(rows){return rows.length?`<div class="work-list">${rows.map(r=>{
 const title=S.workText[r.run_id]||Observability.labelKind(r.request_kind);
 const stamp=r.started_at||r.last_event_at;const date=new Date(stamp);
 const time=stamp&&!Number.isNaN(date.getTime())?date.toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'时间未记录';
 return `<button class="work-row" data-run="${escape(r.run_id)}" data-state="${escape(r.status)}" title="${escape(r.run_id)}"><span class="row-icon">${icon('file',17)}</span><span class="work-text"><strong>${escape(title)}</strong><small><time ${stamp?`datetime="${escape(stamp)}"`:''}>${escape(time)}</time><span>· ${escape(r.run_id.slice(-8))}</span></small></span><span class="row-status"><span class="status-dot"></span>${escape(statusText(r.status))}</span></button>`;
 }).join('')}</div>`:empty('还没有工作记录','提交任务后，这里会显示实际运行记录。')}
function projectSelector(){
 const live=S.projectLiveScope;
 const sources=(S.projectSources||[]).filter(s=>s.task_kind!=="enterprise_semantics");if(!sources.length)return '';
 return `<details class="disclosure" ${live?'open':''}><summary>理解已授权项目</summary><form id="project-analysis" class="settings-form"><label>来源<select id="project-source">${sources.map(s=>`<option value="${escape(s.source_id)}">${escape(s.label)} · ${escape(s.object_type)}</option>`).join('')}</select></label><label>希望理解或复用什么<textarea id="project-objective" maxlength="2000" required ${live?'readonly':''}>${escape(live?.objective||'')}</textarea></label><label>分析深度<select id="project-depth"><option value="0">D0 识别</option><option value="1" ${!live?'selected':''}>D1 职责理解</option><option value="2" ${live?'selected':''}>D2 复用分析</option></select></label><button class="primary" type="submit" ${S.sending?'disabled':''}>${live?'开始项目理解':'发送选定项目资料并开始理解'}</button><p class="note">${live?`本次只读实测：最多 ${live.max_requests} 次、¥${escape(live.budget_cny)}；仅公开冻结源码。配置密钥不会自动开始。`:"仅发送 Host 已准入的选定项目资料；不接受任意文件路径。本次点击授权发送该来源当前版本，结果保留证据与未知项。"}</p></form></details>`;
}
function home(){return `<section class="home"><h1>你希望 AI 帮助完成什么？</h1><p class="intro">从需求出发，继续手头的工作。</p>${S.projectLiveScope?`<p class="inline-notice">当前为已批准的单对象项目实测工作区。普通聊天与附件任务关闭，额度只用于下方项目。</p>`:(S.chat?chatPanel():compose())}${projectSelector()}<div class="message-actions"><button id="load-example" class="quiet-link">载入内置非敏感样例 ${icon('arrow',12)}</button></div><p class="note">基础对话可在左下角配置模型；附件提取仍为独立 MOCK，不会因开启聊天而外发。</p><div class="section-heading"><h2>最近工作</h2><div class="section-actions"><a class="quiet-link" href="#runs">查看全部 ↗</a><button class="quiet-link" id="refresh">刷新</button></div></div>${runRows(S.runs.filter(r=>r.request_kind==='natural_language_ask').slice(0,4))}<div class="section-heading"><h2>你的 Agents</h2></div><div class="agent-shortcuts"><button id="new-draft" class="agent-shortcut">${icon('plus',18)}<span><strong>准备 Agent 草案</strong><small>浏览真实能力目录，尚未注册或激活</small></span></button></div>${note()}</section>`}
function itemsOf(){const o=S.result?.observation;return o?.items||o?.semantic_candidate?.items||[]}
function projectReceipt(r){
 const p=r?.result?.output?.project_analysis;if(!p)return '';
 return `<div class="inline-notice">项目方法 ${escape(p.method?.component_id)} @ ${escape(p.method?.version)}<br>方法包 SHA-256：<span class="break-id">${escape(p.method?.package_sha256)}</span><br>源码清单 SHA-256：<span class="break-id">${escape(p.source_manifest_sha256)}</span><br>已达深度：${escape(p.analysis?.achieved_depth??'UNKNOWN')} · 决策状态：${escape(p.analysis?.decision_readiness||'UNKNOWN')}<br>语义质量：${escape(p.semantic_quality||'NOT_EVALUATED')}</div>`;
}
async function loadChat(){
  const selected=S.chatSelection||sessionStorage.getItem('catalyst-workplace-thread');
  try{
    try{S.chat=await api('/api/chat'+(selected?'?thread='+encodeURIComponent(selected):''));}
    catch(error){if(error.status!==404||!selected)throw error;S.chat=await api('/api/chat');}
    S.chatSelection=S.chat.thread_id;
    sessionStorage.setItem('catalyst-workplace-thread',S.chatSelection);
    S.chatError=null;
  }catch(error){if(error.status===404)S.chat=null;else if(error.status!==409)S.chatError='聊天历史暂时无法读取。'}
}
function chatTurn(turn){
  const status=turn.mode==='LIVE_CHAT'
    ?(turn.state==='CHAT_COMPLETED'
      ?(turn.external_calls>0?'模型已回复 · '+turn.model:'模型回复 · 本地验证')
      :'模型对话未完成')
    :'本机说明';
  return `<article class="chat-turn">
    <div class="message user-message"><div class="speaker">你</div><div class="message-text">${escape(turn.message)}</div></div>
    <div class="message"><div class="speaker">Catalyst <small>${escape(status)}</small></div><div class="message-text">${escape(turn.answer)}</div></div>
    <button class="quiet-link" data-chat-run="${escape(turn.run_id)}">查看本轮调用与证据</button>
  </article>`;
}
function chatPanel(current=null){
  const thread=S.chat?.thread_id||current?.chat?.thread_id;
  const turns=S.chat?.turns||[];
  const active=turns.filter(turn=>turn.thread_id===thread);
  if(current?.chat?.thread_id===thread&&current&&!active.some(turn=>turn.run_id===current.run_id)){
    active.push({...current,message:current.chat.message,answer:current.result?.output?.answer||current.error?.code||''});
  }
  const settings=S.settings;
  const connection=settings?.connection_available
    ? '模型已连接 · '+settings.model
    : settings?.configured?'模型连接当前不可用':'模型未连接';
  const pending=!current&&S.route==='work'&&S.chatPending===S.run?.run_id;
  return `<section class="chat-panel" aria-label="对话">
    <div class="chat-heading"><span role="status">${escape(connection)}</span>
      <label>历史对话 <select id="chat-thread-select" ${pending||S.sending?'disabled':''}>${(S.chat?.threads||[]).map(item=>`<option value="${escape(item.id)}" ${item.id===thread?'selected':''}>${escape(item.title)}</option>`).join('')}</select></label>
      <button id="new-chat" class="secondary" ${pending||S.sending?'disabled':''}>新对话</button></div>
    ${S.chatError?`<p class="note">${escape(S.chatError)}</p>`:''}
    ${active.map(chatTurn).join('')}
    ${pending?`<article class="message user-message"><div class="speaker">你</div><div class="message-text">${escape(S.workText[S.run.run_id]||'')}</div></article><p role="status">正在等待回复…</p><button id="cancel" class="secondary">停止后续步骤</button>`:''}
    ${compose()}
    <p class="note">聊天按预算带入所选对话的近期消息。附件任务单独执行。</p>
  </section>`;
}
function work(){const r=S.result;if(r?.chat||(!r&&S.chat&&S.chatPending&&S.chatPending===S.run?.run_id))return head('对话','')+chatPanel(r)+note();return `${head('当前工作',S.run?.run_id||'选择一条运行记录',`<button id="toggle-detail" class="secondary">${icon('layers',14)}${S.detail?'收起详情':'来源与过程'}</button>`)}<div class="task-layout"><section class="conversation">${Observability.stages(S.run?Observability.project(S.run,S.result):null)}${S.run?`<div class="row-status"><span class="status-dot"></span>${escape(statusText(r?.state||S.run.status))} ${badge(r?.mode||'本地记录')}</div>`:''}${S.workText[S.run?.run_id]?`<article class="message user-message"><div class="speaker">你</div><div class="message-text">${escape(S.workText[S.run.run_id])}</div></article>`:''}${r?`<article class="message"><div class="speaker"><span class="avatar">C</span>Catalyst</div><div class="message-text">${escape(r.result?.output?.answer||r.error?.code||'没有已确认的回答')}</div></article><div class="inline-notice">实际入口：${escape(r.execution_entry||'历史入口')}<br>${r.task_type==='basic_chat'?(r.asset_read_verified?'已实际读取 Wiki 产品资产':'文本对话 · 尚无成功资产读取证据'):`Runtime：${escape(r.result?.output?.project_analysis?.runtime_status||r.capture?.runtime_terminal||'UNKNOWN')} · 结构捕获：${escape(r.capture?.typed_capture??'UNKNOWN')}`}<br>独立业务语义评价：NOT_EVALUATED · Wiki Candidate：${escape(r.candidate_id||'无')} · 正式版本：${escape(r.version_id||'无')}</div>${r.workflow||r.test_plan?`<p class="inline-notice">${r.test_plan?"AI 测试配置已准备，尚未执行测试。":"测试方案已独立保存，未执行。"}<a href="#experiments">前往 Development →</a></p>`:''}${projectReceipt(r)}${itemsOf().length?`<h2>捕获的候选条目</h2><ul class="fact-list">${itemsOf().map(i=>`<li><small>${escape(i.kind)} · ${escape(i.item_id||i.key)} · ${escape(i.evidence_class||'')}</small>${escape(i.meaning)}${i.uncertainty?`<p class="note">${escape(i.uncertainty)}</p>`:''}</li>`).join('')}</ul>`:''}<details class="disclosure"><summary>查看实际结果与捕获收据</summary><pre class="raw-json">${escape(JSON.stringify(r,null,2))}</pre></details>`:empty('等待实际结果','结果提交前不推断完成；可以刷新读取当前状态。')}<div class="message-actions"><button class="secondary" id="to-agent">延续为 Agent 草案</button>${S.run?.status==='running'?'<button class="secondary" id="cancel">停止后续步骤</button>':''}<button class="quiet-link" id="refresh">刷新</button></div><p class="note">基础文本对话使用同一模型 scope 的最近 6 条上下文；每次提交产生独立运行。附件任务不混入聊天上下文。</p>${!r||r.task_type==='basic_chat'?compose():''}</section>${S.detail?`<aside class="detail-panel"><h2>来源与证据</h2><ul class="fact-list"><li><small>来源 SHA-256</small><span class="break-id">${escape(r?.result?.output?.project_analysis?.source_manifest_sha256||r?.source_sha256||'UNKNOWN')}</span></li><li><small>网络 / MOCK 调度</small>实际外发 ${escape(r?.external_calls??'UNKNOWN')} 次<br>本地模拟 ${escape(r?.logical_mock_dispatches??'UNKNOWN')} 次</li><li><small>捕获边界</small>${escape(r?.capture?.boundary||'UNKNOWN')}</li></ul><button class="quiet-link" id="show-run">查看真实 R4 →</button></aside>`:''}</div>${note()}`}
function capRows(q=''){const rows=S.caps.filter(c=>c.id!=='wiki_assets').filter(c=>(capName(c)+c.description+c.id).toLowerCase().includes(q.toLowerCase()));return rows.map(c=>{const ref=`${c.id}@${c.version}`;return `<div class="cap-item" draggable="true" data-cap="${escape(ref)}"><div><h3>${escape(capName(c))}</h3><p>${escape(c.description)}</p><small>${escape(ref)} · ${c.active?'已活动，权限未推断':'Host 有界授权后才可见'}</small></div><button class="icon-button" data-add="${escape(ref)}" aria-label="添加${escape(capName(c))}" ${S.selected.includes(ref)?'disabled':''}>${S.selected.includes(ref)?'✓':'+'}</button></div>`}).join('')||'<p class="note">没有匹配能力。</p>'}
function agents(){return `${head('Agents','按职责准备草案；能力来自当前真实 Harness Catalog。',`<button id="toggle-caps" class="secondary">${icon('layers',14)}${S.capOpen?'收起能力':'浏览能力'}</button>`)}<div class="task-layout"><section class="conversation"><div class="section-heading section-flush"><h2>${S.draftSaved?'内存中已保留的草案':'Agent 草案'}</h2>${badge('未注册 · 未验证')}</div>${S.draftMessages.map(m=>`<article class="message user-message"><div class="message-text">${escape(m)}</div></article>`).join('')}<p class="intro">选择能力表达组合偏好。当前未接通 Agent 生成、组合验证或注册服务。</p>${compose(true)}<div class="message-actions"><button id="save-draft" class="secondary">保留内存草案</button></div><p class="note">输入不会调用模型；刷新会清空草案。资料只在回首页提交任务时上传。</p></section>${S.capOpen?`<aside class="cap-panel"><div class="panel-heading"><h2>Capabilities</h2>${badge('真实 Catalog')}</div><input id="cap-search" class="search" aria-label="搜索能力" placeholder="搜索希望完成的工作…"><p class="note">添加能力不授予运行权限，也不改变绑定。</p><div id="cap-results">${capRows()}</div></aside>`:''}</div>${note()}`}
// KNOWLEDGE_SURFACE_BEGIN
const toBase64=bytes=>{let binary='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk)binary+=String.fromCharCode.apply(null,bytes.subarray(i,i+chunk));return btoa(binary)};
const nativeFormat=f=>['docx','pptx','pdf'].includes(String(f||'').toLowerCase());
function wikiSourceView(source){const s=source||{};const sha=s.current_revision||s.source_revision||'';const rows=[];
 if(s.source_format)rows.push(badge(nativeFormat(s.source_format)?`原生文档 · ${String(s.source_format).toUpperCase()}`:'Markdown 来源'));
 if(s.status==='WITHDRAWN')rows.push(badge('已撤销登记'));
 if(s.fresh===false)rows.push(badge('磁盘内容已变更'));
 if(s.fresh===true)rows.push(badge('与登记一致'));
 const head=`<h2>${escape(s.relative_path||'导入资料')}</h2><p class="doc-meta break-id">${escape(s.authority||'')}<br>SHA：${escape(sha)}</p>`;
 const withdraw=s.source_id&&s.status!=='WITHDRAWN'?`<p><button class="quiet-link" id="wiki-withdraw" data-source="${escape(s.source_id)}">撤销登记</button></p>`:'';
 const body=nativeFormat(s.source_format)
  ?`<p class="intro">这类文件只登记字节身份：Wiki 不保存它的正文，也不会从它推断事实。结构化提案只在提交时由 Understand 重新提取并逐条对齐证据，最终停在候选层。</p>`+empty('原生文档暂不提供正文预览','文件保持原样；打开不会触发解析或推断内容。')
  :(s.content!==null&&s.content!==undefined?`<pre class="document-text">${escape(s.content)}</pre>`:empty('暂无正文预览','文件保持原样；不会根据占位图推断内容。'));
 return `${head}<div class="chips">${rows.join('')}</div>${body}${withdraw}`}
function bindKnowledgeSurface(){const stage=document.querySelector('#wiki-stage'),input=document.querySelector('#wiki-stage-input');
 if(stage&&input)stage.onclick=()=>input.click();
 if(input)input.onchange=async()=>{const file=input.files[0];input.value='';if(!file)return;
  try{const limit=String(file.name).toLowerCase().endsWith('.md')?2*1024*1024:16*1024*1024;
   if(file.size>limit)throw new Error('文件超过 Wiki 登记上限');
   const receipt=await api('/api/knowledge/stage',{name:file.name,data_base64:toBase64(new Uint8Array(await file.arrayBuffer()))});
   S.error=null;await refresh();
   toast(receipt.status==='CANDIDATE_STAGED'?`已登记为来源并进入候选层 · ${receipt.evidence_count} 条证据`:receipt.status==='STAGED_WITHOUT_CANDIDATE'?'已登记为来源；没有可提取的正文，未生成候选':'已登记为来源');
  }catch(e){S.error=e.message;render()}};
 const withdraw=document.querySelector('#wiki-withdraw');
 if(withdraw)withdraw.onclick=async()=>{try{await api('/api/knowledge/withdraw',{source_id:withdraw.dataset.source});S.source=null;await refresh();toast('已撤销登记，历史记录保留')}catch(e){S.error=e.message;render()}}}
// KNOWLEDGE_SURFACE_END
function wikiButtons(){return '<button class="quiet-link" id="wiki-stage">登记文件</button><input type="file" id="wiki-stage-input" accept=".md,.docx,.pptx,.pdf" hidden><button class="quiet-link" id="refresh">刷新目录</button>'}
function wikiTabs(){return `<div class="ontology-tabs" role="group" aria-label="Wiki 视图"><button id="wk-read" aria-pressed="${S.wikiTab==='read'}" class="${S.wikiTab==='read'?'selected':''}">知识阅读</button><button id="wk-sources" aria-pressed="${S.wikiTab!=='read'}" class="${S.wikiTab!=='read'?'selected':''}">来源资料与资产</button></div>`}
function wikiEvDetail(m){if(!S.wikiEv||!m.evidence||!m.evidence[S.wikiEv])return '';return `<div id="wk-ev-detail" class="wk-ev-detail">${WikiContract.evidenceDetail(m.evidence[S.wikiEv])}</div>`}
// The workbench reader draws the same blocks the standalone page draws: one nav, one field
// split, one evidence list, one backlink list, one admission banner - all from WikiContract.
function wikiReader(){const m=S.wikiModel;if(S.wikiError)return empty('无法读取 Wiki',WikiContract.errorText(S.wikiError,S.wikiError));if(!m)return empty('正在读取 Wiki','读取由 /api/wiki/model 提供，不写任何文件。');const pages=m.pages||[];if(!pages.length)return empty('这个范围还没有页面','Wiki 里没有已接纳的知识，也没有已登记的来源。');
const resolved=WikiContract.resolvePage(m,S.wikiPage);const page=resolved.page;if(!page)return empty('这个范围里没有这个页面',`地址里的 page=${resolved.missing} 不在本范围的页面集里。左侧列表可换一页；地址不会静默改写成别的文档。`);
const meta=m.meta||{};const activeVersion=meta.active_version_id||'';const byPath=new Map(pages.map(p=>[p.path,p]));
const backlinks=(page.backlinks||[]).length?`<section class="wk-backlinks"><h2>谁指向这里</h2>${WikiContract.backlinksHtml(page,byPath)}</section>`:'';
const reader=WikiContract.readerUrl({scope:meta.scope||'',page:page.path,anchor:(page.toc&&page.toc[0]||{}).id,version:activeVersion});
return `<p class="note">范围 ${escape(meta.scope||'')} · 版本 ${escape(activeVersion||'无')} · 页面 ${pages.length} · 校验 ${escape((meta.verify||{}).status||'')} · <a class="quiet-link" href="${escape(reader)}">完整阅读页 ↗</a></p><div class="library"><aside><input id="wk-q" class="search" placeholder="检索标题、正文、键…" aria-label="检索 Wiki 页面" value="${escape(S.wikiQuery||'')}"><nav class="wiki-nav" id="wiki-nav">${WikiContract.navHtml(m,{current:page.path,query:S.wikiQuery||''})}</nav><p class="note" id="wk-hit">${pages.length} 页</p></aside><article class="doc-body" id="wk-inline">${WikiContract.versionNotice(m,S.wikiVersion)}${WikiContract.admission(m,page)}<h2>${escape(page.title)}</h2>${WikiContract.tocHtml(page)}${WikiContract.objectChips(page.objects)}${WikiContract.fieldsHtml(page)}${page.html}${WikiContract.evidenceHtml(page,m.evidence,S.wikiEv)}${wikiEvDetail(m)}${backlinks}</article></div>`}
function wiki(){return `${head('Wiki','知识阅读、来源资料与系统资产的统一入口。',badge(S.wikiTab==='read'?'知识阅读':'来源资料与资产')+wikiButtons())}${wikiTabs()}${scopeBar()}${S.wikiTab==='read'?wikiReader():`<div class="library"><aside><button class="quiet-link" id="wiki-overview">${icon('wiki',14)} 目录总览</button><p class="cap-group">已整理的来源 · ${S.docs.length}</p><div class="doc-menu">${S.docs.map(d=>`<button data-doc="${escape(d.source_id)}">${icon('file',14)}${escape(d.title)}${d.source_format?`<small class="preview-label">${escape(String(d.source_format).toUpperCase())}</small>`:''}</button>`).join('')||'<p class="note">暂无已整理来源；资产目录可独立查看。</p>'}</div><p class="cap-group">待整理资料 · ${S.imports.length}</p><div class="doc-menu">${S.imports.map(d=>`<button data-import="${escape(d.id)}">${icon('file',14)}${escape(d.id.slice(0,12)+'…'+d.id.slice(-5))}</button>`).join('')||'<p class="note">暂无导入资料。</p>'}</div>${assetSection()}</aside><article class="doc-body">${S.assetUnavailable?empty('资产当前不可读','登记文件发生变化或所选版本不再可用，请刷新并重新选择。'):S.asset?assetDocument(S.asset):S.source?wikiSourceView(S.source):`<h2>Wiki 工作目录</h2><p class="intro">这里保存产品资产的说明与引用；登记不等于运行授权，也不代表企业本体正式接纳。</p><div class="wiki-directory"><div><strong>Capabilities</strong><span>${S.assets.length} 项已登记资产</span><small>系统组件、业务动作、方法；从左侧展开查看。</small></div><div><strong>来源档案</strong><span>${S.docs.length} 份已整理来源</span><small>原始证据与版本独立保存。</small></div><div><strong>待整理资料</strong><span>${S.imports.length} 份导入资料</span><small>导入不代表已评价或接纳。</small></div></div><p class="note">测试建议：在模型设置显式允许产品资产摘要查询后，回首页问“系统现在有哪些资产，它们如何连接？”；是否真正读取，以运行记录中的 Wiki 资产工具结果为准。</p>`}</article></div>`}${note()}`}

function openWikiPage(path){if(!path)return;S.wikiPage=path;S.wikiEv=null;history.replaceState(null,'',WikiContract.buildHash('wiki',{scope:S.scope,page:S.wikiPage,version:(S.wikiModel&&S.wikiModel.meta||{}).active_version_id}));render()}
// The same evidence drawer the standalone page opens, rendered inside the article.
function showInlineEvidence(id){if(!id)return;S.wikiEv=S.wikiEv===id?null:id;render();const box=$('#wk-ev-detail');if(box)box.scrollIntoView({block:'nearest'})}
function enterpriseBackHash(){return WikiContract.buildHash('enterprise',{scope:S.scope,candidate:S.candidateId||S.result?.candidate_id||null,object:S.graphFocus||null,evidence:S.graphEvidence?'1':null,version:S.wikiModel?.meta?.active_version_id||null})}
function businessGraphContext(){return {scope:S.scope,version:S.wikiModel?.meta?.active_version_id||null,pageFor:key=>{const pages=S.wikiModel?.pages||[];const page=pages.find(p=>p.kind==='entity'&&p.fields&&p.fields.canonical_key===key);return page?page.path:null},backHash:enterpriseBackHash()}}
function setGraphFocus(id){S.graphFocus=id||null;S.graph=null;history.replaceState(null,'',enterpriseBackHash());render();loadRoute()}
function setGraphEvidence(on){S.graphEvidence=!!on;S.graph=null;history.replaceState(null,'',enterpriseBackHash());render();loadRoute()}
function graphView(g){if(g?.schema==='catalyst.understand_business_graph.v1')return BusinessGraph.panel(g,businessGraphContext());return legacyGraphView(g)}
function legacyGraphView(g){const nodes=g?.nodes||[],edges=g?.edges||[];if(!nodes.length)return empty('没有可展示的节点',S.graphTier==='accepted'?'当前没有已接纳的正式本体版本。':'该候选暂无有界图投影。');const width=760,height=Math.max(350,Math.ceil(nodes.length/3)*95+40);const points=new Map(nodes.map((n,i)=>[n.id,{x:35+(i%3)*245,y:30+Math.floor(i/3)*95}]));return `<div class="graph-wrap"><svg viewBox="0 0 ${width} ${height}" height="${height}" aria-label="实际本体投影"><defs><marker id="arrowhead" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 10 5 0 10z" fill="#bcc4b1"/></marker></defs>${edges.map(e=>{const a=points.get(e.source||e.from),b=points.get(e.target||e.to);return a&&b?`<path class="graph-edge" marker-end="url(#arrowhead)" d="M${a.x+90} ${a.y+25} L${b.x+90} ${b.y+25}"/>`:''}).join('')}${nodes.map(n=>{const p=points.get(n.id);return `<g class="graph-node" data-node="${escape(n.id)}" role="button" tabindex="0"><rect x="${p.x}" y="${p.y}" width="180" height="50" rx="7"/><text x="${p.x+90}" y="${p.y+30}" text-anchor="middle">${escape((n.meaning||n.name||n.label||n.type||n.id).slice(0,14))}</text></g>`}).join('')}</svg></div><details class="disclosure"><summary>对象与关系原始投影 · ${nodes.length} 节点 / ${edges.length} 边</summary><pre class="raw-json">${escape(JSON.stringify(g,null,2))}</pre></details>`}
function adjustCandidate(){const rows=S.semanticCandidates?.candidates||[];if(S.candidateId&&!rows.some(r=>r.candidate_id===S.candidateId))S.candidateId=null;if(S.candidateId||S.result?.candidate_id||!rows.length)return;const pick=rows.find(r=>String(r.type||'').startsWith('understand'))||rows.find(r=>r.version_id)||rows[0];S.candidateId=pick.candidate_id}
function tierBadge(){if(S.graphTier!=='accepted')return badge('候选视图');const a=S.graph?.authority_class;return badge(a==='test_only'?'测试准入（test_only）':a?('正式准入：'+a):'无已接纳版本')}
function candidateDigest(){const rows=S.semanticCandidates?.candidates||[];const current=S.candidateId||S.result?.candidate_id||'';const row=rows.find(r=>r.candidate_id===current);if(!row)return '';return `<p class="note">候选摘要：${escape((row.content_digest||'').slice(0,12))} · 裁定：${escape(row.decision?(row.revision_matches_decision?'绑定当前修订':'候选或修订已变，旧裁定不覆盖'):'尚未裁定')} · 来源修订：${escape((row.source_revision||'').slice(0,12))}</p>`}
function semanticPicker(){const rows=S.semanticCandidates?.candidates||[];if(!rows.length)return '';const current=S.candidateId||S.result?.candidate_id||'';return `<p class="note">候选：<select id="semantic-candidate"><option value="">（不选，只看正式本体）</option>${rows.map(r=>`<option value="${escape(r.candidate_id)}"${r.candidate_id===current?' selected':''}>${escape(r.candidate_id)} · ${escape(r.type||'')}${String(r.type||'').startsWith('understand')?'':'（无候选图）'} · ${escape(r.status||'')}${r.decision?' · '+escape(r.decision):''}${r.version_id?' · 已入版本':''}</option>`).join('')}</select></p>`}
function scopeRows(){return (S.scopes&&S.scopes.scopes)||[]}
function currentScope(){const rows=scopeRows();return rows.find(r=>r.scope_id===S.scope)||rows.find(r=>r.scope_id===S.scopes?.daily)||null}
function scopeBar(){const rows=scopeRows();if(rows.length<2)return '';const cur=currentScope();return `<p class="note">知识范围：<select id="scope-select">${rows.map(r=>`<option value="${escape(r.scope_id)}"${r.scope_id===cur?.scope_id?' selected':''}>${escape(r.label)} · ${escape(r.scope_id)}${r.read_only?' · 只读':''}${r.has_store?'':' · 无存储'}</option>`).join('')}</select>${cur?.read_only?' <span class="preview-label">测试准入 · 只读</span>':''}${cur?.read_only?'<small> 只读范围只用来查看，不提供准入或激活。</small>':''}</p>`}
function runProductPanel(){
const items=(S.runProducts?.items)||[];if(!items.length)return '';
// One dropped row states what is known: the rule, the item's own evidence class, and the
// reference ladder (record present -> quote recorded -> location recorded -> original readable).
const ladderCell=r=>{const e=r.evidence||{};const parts=[];
 if(e.declared!=null)parts.push(`引用 ${e.present}/${e.declared} 在记录里${e.missing&&e.missing.length?'（缺 '+e.missing.slice(0,3).map(escape).join('、')+'）':''}`);
 if(e.with_quote!=null)parts.push(`${e.with_quote} 条带原句`);
 if((e.locators||[]).length)parts.push('位置 '+e.locators.slice(0,2).map(x=>`<code>${escape(x)}</code>`).join(' · '));
 if((e.originals||[]).length)parts.push('原件 '+e.originals.slice(0,2).map(escape).join('、'));
 parts.push(e.original_readable?'原件可读':'原件本轮不可读');
 return `${escape(r.rule_label||'')}（${escape(r.rule||'')}）${r.evidence_class?' · 条目证据类别 '+escape(r.evidence_class):''}<small>${parts.join(' · ')}</small>`};
const rowsTable=(rows,dropped)=>`<table class="objects-table"><thead><tr><th>条目</th><th>类型</th><th>原文</th><th>位置</th><th>${dropped?'规则与依据':'去向'}</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="break-id">${escape(r.item_id||'')}</td><td>${escape(r.kind||'')}</td><td>${escape((r.meaning||'').slice(0,200))}</td><td>${escape(r.line_start?('第'+r.line_start+(r.line_end&&r.line_end!==r.line_start?'–'+r.line_end:'')+' 行'):(r.heading||'—'))}</td><td>${dropped?ladderCell(r):escape(r.reason||'—')}</td></tr>`).join('')}</tbody></table>`;
return items.map(p=>{
 if(!p.readable)return `<section class="section-card"><h2>${escape(p.label)}</h2><p class="inline-notice">${escape(p.message||p.error||'')}</p></section>`;
 const c=p.counts||{};const carried=(p.rows||[]).filter(r=>r.status==='carried');const dropped=(p.rows||[]).filter(r=>r.status==='dropped');
 const opinionBlock=opinionForm(p);
 const ladder=c.dropped_ladder||{};const ladderNote=ladder.with_quote!=null?`带原句 ${ladder.with_quote} · 无原句 ${ladder.without_quote||0} · 引用记录缺失 ${ladder.records_missing||0}`:'—';
 return `<section class="section-card"><h2>${escape(p.label)} · 完整建模候选</h2><p class="note">受控运行的只读投影，不写 Wiki、不改变正式准入。共 ${c.rows} 行：已递交 ${c.carried} · 未收获 ${c.dropped}${c.dropped_unaccounted?' · 未对上 '+c.dropped_unaccounted:''}。候选 ${escape(p.candidate_id)}。<br>来源目录 ${escape(p.root)}</p>
 <p class="note">按类型：${Object.entries(c.by_kind||{}).map(([k,v])=>escape(k)+' '+v).join(' · ')||'—'}<br>按规则：${Object.entries(c.by_rule||{}).map(([k,v])=>escape(k)+' '+v).join(' · ')||'无'}<br>未收获的依据阶梯：${ladderNote}</p>
 <p class="note">规则码只说这一行为什么没进候选；引用能不能读是另一件事，下面逐行分开写。原件回查本轮不做，所以原件一列一律写“不可读”，不用派生行冒充原件。</p>
 <details class="disclosure"><summary>未收获条目 · ${dropped.length}</summary>${rowsTable(dropped,true)}</details>
 <details class="disclosure"><summary>已递交 Wiki 的部分 · ${carried.length}</summary>${rowsTable(carried,false)}</details>${opinionBlock}</section>`}).join('')}

// One opinion at a time, bound to the row the reviewer was reading. The ledger is separate from
// the candidate's disposition on purpose: leaving an opinion is not reviewing the candidate.
function opinionForm(p){
 const rows=p.rows||[];if(!rows.length)return '';
 const cid=p.candidate_id,mine=((S.opinions&&S.opinions.effective)||[]).filter(o=>o.candidate_id===cid);
 const known=new Map(mine.map(o=>[o.item_id,o]));const stances=(S.opinions&&S.opinions.stances)||{agree:'同意',question:'存疑',reject:'驳回'};
 const options=rows.slice(0,200).map(r=>`<option value="${escape(r.item_id)}">${escape(r.item_id)} · ${escape(String(r.meaning||'').slice(0,40))}${known.has(r.item_id)?' · 已留'+escape(stances[known.get(r.item_id).stance]||known.get(r.item_id).stance):''}</option>`).join('');
 const saved=mine.map(o=>`<li>${escape(o.item_id)} · ${escape(stances[o.stance]||o.stance)} · ${escape(o.reason||'')}</li>`).join('');
 return `<details class="disclosure"><summary>逐条意见 · 已留 ${mine.length} 条</summary>
 <p class="note">逐条意见只记录审阅看法：不改变条目资格、不创建版本、不改准入。它绑定这条内容当时的摘要，内容一变旧意见就作废，不会跟着新内容走。</p>
 <div class="settings-form"><label>条目<select id="opinion-item">${options}</select></label>
 <label>看法<select id="opinion-stance"><option value="agree">同意</option><option value="question">存疑</option><option value="reject">驳回</option></select></label>
 <label>理由<textarea id="opinion-reason" maxlength="2000" placeholder="写清楚这条为什么存疑或驳回"></textarea></label>
 <button class="primary" id="opinion-save" type="button">记下这条意见</button></div>
 <p id="opinion-message" class="note" role="status"></p>${saved?`<ul class="note">${saved}</ul>`:''}</details>`}
function dispositionPanel(){const rows=S.semanticCandidates?.candidates||[];const cid=S.candidateId||S.result?.candidate_id;const row=rows.find(r=>r.candidate_id===cid);if(!cid||!row)return '';const mine=(S.dispositions?.effective||[]).find(r=>r.candidate_id===cid);const label={ACCEPTED:'接受',DEFERRED:'延后',REJECTED:'拒绝'};return `<section class="section-card"><h2>审阅处置</h2>${(()=>{const cov=S.opinions&&S.opinions.coverage;return cov?`<p class="note">逐条覆盖：留过意见 ${cov.with_opinion} 条 · 仍有疑问 ${cov.still_question} 条 · 本次未覆盖 ${cov.uncovered} 条${cov.stale?' · 内容已变、意见作废 '+cov.stale+' 条':''}${cov.legacy?' · 旧规则、需重新核对 '+cov.legacy+' 条':''}。留过意见不等于审完，整体接受也不代表没留意见的条目被审过。</p>`:''})()}<p class="note">处置是审阅意见，不是 Wiki 准入：不创建版本、不激活、不改变知识范围。它绑定候选摘要 ${escape((row.content_digest||'').slice(0,12))}，候选内容一变就作废。</p>${mine?`<p class="note">当前：${escape(label[mine.action]||mine.action)} · ${escape(mine.at||'')} · 理由：${escape(mine.reason||'')}</p><details class="disclosure"><summary>撤回这条处置</summary><form id="withdraw-form" class="settings-form"><label>撤回理由<textarea name="reason" maxlength="2000" required></textarea></label><button class="secondary" type="submit">撤回</button></form></details>`:'<p class="note">还没有处置记录。</p>'}<form id="disposition-form" class="settings-form"><label>处置<select name="action" required><option value="">请选择（不预选接受）</option><option value="ACCEPTED">接受</option><option value="DEFERRED">延后</option><option value="REJECTED">拒绝</option></select></label><label>理由<textarea name="reason" maxlength="2000" required></textarea></label><button class="primary" type="submit">记录处置</button></form><p id="disposition-message" class="note" role="status"></p></section>`}
// One card for the whole modelling task: material, candidate, version, what was read, what was
// not, and what review recorded. Every number is read from this scope's own records; a missing
// one is written as missing instead of being estimated. Test admission is not business adoption.
function modelTaskCard(){
 const m=S.wikiModel;if(!m)return '';
 const meta=m.meta||{},cands=(S.semanticCandidates&&S.semanticCandidates.candidates)||[];
 const products=(S.runProducts&&S.runProducts.items)||[],ledger=(S.dispositions&&S.dispositions.effective)||[];
 const version=((S.semanticCandidates&&S.semanticCandidates.versions)||[]).find(v=>v.version_id)||{};
 const kinds=meta.meanings||{},n=k=>Number(kinds[k]||0);
 const cell=(label,value)=>`<span class="wiki-kv">${escape(label)} <b>${escape(String(value))}</b></span>`;
 const proposer=cands.map(c=>c.proposer_origin).find(Boolean);
 const candidates=cands.length?cands.map(c=>`${c.type==='native'?'原生提交':'Understand 提交'} · ${c.status}`).join('；'):'没有候选';
 return `<section class="task-card"><h2>本次建模任务</h2>
  <div class="chips">${cell('资料',((meta.sources||{}).recorded||0)+' 份')}${cell('候选',cands.length+' 个')}${cell('版本',version.version_id?String(version.version_id).slice(0,18)+'…':'无')}${cell('准入',version.authority_class||'没有记录')}${cell('准入依据',version.acceptance_basis_state==='recorded'?'已记录 · '+((version.acceptance_basis||{}).issuer_id||'issuer 未记录'):'未记录业务批准依据')}${cell('已接受条目',(meta.meanings_total||0)+' 条')}${cell('职责/事件/条件',`${n('duty')}/${n('event')}/${n('condition')}`)}${cell('未收获',products.length+' 条')}${cell('已记处置',ledger.length+' 条')}</div>
  <p class="note">候选：${escape(candidates)}。提出者：${escape(proposer||'没有记录')}。方法身份：${escape(proposer?'没有记录（候选行只记了提出者，没有方法包标识）':'没有记录')}。</p>
  <p class="inline-notice">已做测试准入（${escape(version.authority_class||'没有记录')}）不等于业务正式采用；业务批准依据：${escape(version.acceptance_basis_state==='recorded'?'已记录（'+((version.acceptance_basis||{}).issuer_id||'issuer 未记录')+'）':'未记录业务批准依据')}。处置只记录审阅结论，不新增版本、不改准入。</p></section>`;
}
function enterprise(){const cid=S.candidateId||S.result?.candidate_id;const rows=S.semanticCandidates?.candidates||[];return `${head('Enterprise','查看待审阅的候选与已接纳的正式本体。',tierBadge())}${modelTaskCard()}<div class="ontology-tabs" role="group" aria-label="本体视图"><button id="candidate-graph" aria-pressed="${S.graphTier==='candidate'}" class="${S.graphTier==='candidate'?'selected':''}">候选本体</button><button id="accepted-graph" aria-pressed="${S.graphTier==='accepted'}" class="${S.graphTier==='accepted'?'selected':''}">正式本体</button></div>${scopeBar()}${S.graphTier==='candidate'?semanticPicker()+candidateDigest():''}${S.graphTier==='candidate'&&cid&&!String((rows.find(r=>r.candidate_id===cid)||{}).type||'').startsWith('understand')?empty('该候选没有候选图','原生提交的候选没有 Understand 候选图；它的去向见裁定与版本。'):(S.graphTier==='candidate'&&!cid?(S.candidateError?empty('无法读取候选列表',S.candidateError):empty('暂无候选本体',rows.length?'从上面选择一个候选。':'这个 Wiki 范围里还没有候选；未接纳内容不会显示为正式本体。')):S.graphError?empty('无法读取图谱',S.graphError):S.graph?graphView(S.graph):empty('正在读取','查询由原 Wiki 接口处理，并记录实际消费事件。'))}<p class="note">版本：${escape(S.graph?.active_version_id||S.graph?.version_id||'无')} · 范围：${escape(S.graph?.scope_id||S.meta?.scope_id)}${S.graph?.authority_class?' · 准入：'+escape(S.graph.authority_class):''}${S.graph?.authority_class&&S.graph.view_tier==='accepted'?' · 准入依据：'+escape(S.graph.acceptance_basis?('已记录 · '+(S.graph.acceptance_basis.issuer_id||'issuer 未记录')):'未记录业务批准依据'):''}${S.routeParams?.version&&S.graph?.active_version_id&&S.routeParams.version!==S.graph.active_version_id?'<br><span class="bg-warn">地址指向的版本已变化：地址 '+escape(String(S.routeParams.version).slice(0,18))+'… · 当前 '+escape(String(S.graph.active_version_id).slice(0,18))+'…</span>':''}<br>${escape((S.graph?.warnings||[]).join(' · '))}${S.graph?.budget?.truncated?'<br>图已截断：显示 '+S.graph.budget.node_count+' 个节点（预算 '+S.graph.budget.node_limit+'）。':''}<br>共享 capture 只捕获方法输出，不自动生成已入库 Wiki Candidate。图谱查询可产生本机审计事件。</p>${dispositionPanel()}${runProductPanel()}${note()}`}
