 return `<h2>${escape(a.title)}</h2><p class="doc-meta break-id">${escape(a.asset_id)} · ${escape(a.version)}<br>${escape(a.integrity)} · 产品资产说明，不是企业 Authority</p><p>${escape(a.responsibility)}</p><div class="wiki-directory"><div><strong>接口</strong><span>${escape(a.interface.id)} · ${escape(a.interface.version)}</span></div><div><strong>生命周期</strong><span>${escape(a.lifecycle)}</span><small>${a.kind==='action'?`当前 Catalog：${a.catalog_registered?'已登记':'未绑定'} · ${a.catalog_active?'活动':'未活动'}`:'由可信 Host 装配；不是模型工具。'}</small></div><div><strong>验收准备</strong><span>${a.tests.length} 个源码 / 测试引用</span><small>引用不等于测试已通过；独立候选仍需运行验收。</small></div></div><h3>连接与依赖</h3>${S.assetGraphError?`<p class="note">${escape(S.assetGraphError)}</p>`:connections.length?`<ul class="fact-list">${connections.map(e=>`<li>${escape(e.from)} → ${escape(e.to)}<small>源码装配依赖说明；不是实时调用轨迹。${e.condition?escape(e.condition):''}</small></li>`).join('')}</ul>`:'<p class="note">没有登记的连接；不自动猜测。</p>'}<h3>使用边界</h3><ul>${a.limits.map(x=>`<li>${escape(x)}</li>`).join('')}</ul><details class="disclosure"><summary>实现、哈希与验收引用</summary><pre class="raw-json">${escape(JSON.stringify({implementation:a.implementation,tests:a.tests,provides:a.provides,requires:a.requires,record_sha256:a.record_sha256},null,2))}</pre></details>`;
