 if($('#accepted-graph'))$('#accepted-graph').onclick=()=>{S.graphTier='accepted';S.graph=null;S.graphFocus=null;S.graphEvidence=false;history.replaceState(null,'',WikiContract.buildHash('enterprise',{scope:S.scope}));render();loadRoute()};if($('#candidate-graph'))$('#candidate-graph').onclick=()=>{S.graphTier='candidate';S.graph=null;render();loadRoute()};if($('#semantic-candidate'))$('#semantic-candidate').onchange=e=>{S.candidateId=e.target.value||null;S.graph=null;S.graphError=null;render();loadRoute()};
