const opinionSave=$('#opinion-save');if(opinionSave)opinionSave.onclick=async()=>{const cid=S.candidateId||S.result?.candidate_id;const product=(S.runProducts?.items||[]).find(p=>p.candidate_id===cid&&p.readable);const item=$('#opinion-item')?.value;const row=((product&&product.rows)||[]).find(r=>r.item_id===item);const message=$('#opinion-message');const reason=($('#opinion-reason')?.value||'').trim();if(!row){if(message)message.textContent='没有找到这条条目，请重新读取运行产物。';return}if(!reason){if(message)message.textContent='写一句理由再记；理由必填。';return}opinionSave.disabled=true;try{const out=await api('/api/review-item-opinions',{scope_id:S.scope,candidate_id:cid,item_id:item,content_digest:row.digest,stance:$('#opinion-stance').value,reason});await loadRoute();toast('已记下逐条意见 '+String(out.record_id||'').slice(0,20)+'（不是准入）')}catch(error){if(message)message.textContent='未记录：'+error.message;opinionSave.disabled=false}};
const dispositionForm=$('#disposition-form');if(dispositionForm)dispositionForm.onsubmit=async event=>{event.preventDefault();const data=new FormData(dispositionForm);const rows=S.semanticCandidates?.candidates||[];const cid=S.candidateId||S.result?.candidate_id;const row=rows.find(r=>r.candidate_id===cid);if(!row)return;const button=dispositionForm.querySelector('[type=submit]');button.disabled=true;try{const out=await api('/api/review-dispositions',{scope_id:S.semanticCandidates?.scope_id||S.scope,candidate_id:cid,content_digest:row.content_digest,action:data.get('action'),reason:data.get('reason')});S.dispositions=await api('/api/review-dispositions?scope='+encodeURIComponent(S.semanticCandidates?.scope_id||S.scope));render();loadRoute();toast('已记录处置回执 '+out.record_id.slice(0,20)+'（不是 Wiki 准入）')}catch(error){$('#disposition-message').textContent='未记录：'+error.message;button.disabled=false}};
const withdrawForm=$('#withdraw-form');if(withdrawForm)withdrawForm.onsubmit=async event=>{event.preventDefault();const rows=S.semanticCandidates?.candidates||[];const cid=S.candidateId||S.result?.candidate_id;const mine=(S.dispositions?.effective||[]).find(r=>r.candidate_id===cid);if(!mine)return;try{await api('/api/review-dispositions',{withdraw:mine.record_id,reason:new FormData(withdrawForm).get('reason')});S.dispositions=await api('/api/review-dispositions?scope='+encodeURIComponent(S.semanticCandidates?.scope_id||S.scope));render();loadRoute();toast('已撤回；原记录保留')}catch(error){toast(error.message)}};
