async function maintenanceAction(action,rid,target){
 const messages={approve:'确认这个精确组件版本及验证结果？确认后仍须重启，不批准企业知识。',reject:'拒绝此更新？已保存的验证证据会保留。',rollback:'确认回退到此更新前的组件版本（可能为未启用）？仍须重启。',restart:'确认重启本地工作区？将清除内存中的模型凭证；未决费用会阻止重启。'};
 if(messages[action]&&!window.confirm(messages[action]))return;
 let data=action==='prepare'&&target?{target}:{};
 if(['approve','reject','rollback'].includes(action)){const row=S.maintenance?.items?.find(r=>r.review_id===rid);if(!row){toast('审阅身份已变化，请刷新');return;}data={review_id:row.review_id,approval_digest:row.approval_digest,confirmed:true};}
 if(action==='restart')data={confirmed:true};
 document.querySelectorAll('[data-maintenance]').forEach(b=>b.disabled=true);
 try{await api('/api/maintenance',{action,data});if(action==='restart'){toast('正在重启，模型凭证不会自动恢复');let ready=false;for(let i=0;i<30;i++){await new Promise(r=>setTimeout(r,1000));try{const next=await api('/api/config');if(!next.csrf_token||next.csrf_token===S.csrf)continue;S.csrf=next.csrf_token;S.meta=await api('/api/workspace');S.caps=(await api('/api/capabilities')).items;ready=true;break;}catch(e){}}if(!ready)throw Error('重启尚未就绪，请刷新或使用回退入口');}await refresh();toast(action==='prepare'?'验证已完成，请查看实际结果':action==='restart'?'重启已完成，请核对启动验收结果':'已记录明确选择；未立即激活')}
 catch(e){S.maintenance={...(S.maintenance||{}),error:e.message};render();toast('操作停止：'+e.message)}
}
function bindMaintenance(){document.querySelectorAll('[data-maintenance]').forEach(b=>b.onclick=()=>maintenanceAction(b.dataset.maintenance,b.dataset.review,b.dataset.target));}
