async function start(){render();try{const meta=await api('/api/workspace');const config=await api('/api/config');const caps=await api('/api/capabilities');try{S.assetGraph=await api('/api/asset-connections');S.assetGraphError=null}catch(e){S.assetGraph=null;S.assetGraphError='连接说明暂不可读'}S.assets=caps.assets||[];S.assetError=caps.asset_error||null;S.settings=await api('/api/settings');const projects=await api('/api/project-sources?include_manifest=1');S.projectSources=projects.items;S.projectLiveScope=projects.live_scope||null;accountMenu();const rs=await api('/api/runs?limit=100');S.meta=meta;S.csrf=config.csrf_token;try{S.scopes=await api('/api/knowledge-scopes');S.scope=S.scopes.daily}catch(e){S.scopes={daily:meta.scope_id,scopes:[]};S.scope=meta.scope_id}S.caps=caps.items;S.runs=rs;S.ready=true;$('#source-identity').textContent=`后端启动身份 ${meta.source_identity.commit}（启动时快照） · 界面 ${Observability.revision} · ${meta.execution_entry}`;render();await loadRoute()}catch(e){S.ready=true;S.error=e.message;render()}}start();

function accountMenu(){
 const profile=S.settings?.profile||{display_name:'本地用户',workspace_name:'本地工作空间'};
 $('.sidebar-bottom').innerHTML=`<details class="account-menu"><summary class="workspace-person" aria-label="用户与模型设置"><span class="avatar">${escape(profile.display_name.slice(0,1))}</span><span class="account-name">${escape(profile.display_name)}<small>${escape(profile.workspace_name)}</small></span><span class="account-dots">···</span></summary><div class="account-popover"><p>本机用户 · 非企业登录</p><button data-settings="profile">个人信息</button><button data-settings="models">模型设置 <span class="status-dot ${(S.settings?.connection_available||S.settings?.enabled)?'connected':''}"></span></button><button data-settings="workspace">工作区与上下文</button></div></details>`;
 document.querySelectorAll('[data-settings]').forEach(el=>el.onclick=()=>{S.settingsTab=el.dataset.settings;$('.account-menu').open=false;go('settings')});
}
function projectLiveSettings(s,l){return `${head('项目实测配置','仅本次 Owner 批准范围；Key 只保留在本机进程内存。')}<p class="inline-notice">${escape(l.scope_id)} · DeepSeek ${escape(l.model||'deepseek-flash')}<br>只发送冻结公开来源、项目目标、方法正文与必要工具结果；不发送企业资料、Gold 或历史私有报告。</p><form id="model-form" class="settings-form"><input name="provider_id" type="hidden" value="deepseek"><input name="model" type="hidden" value="${escape(l.model||'deepseek-flash')}"><label>API Key<input name="api_key" type="password" autocomplete="off" required></label><label>最多请求<input name="max_requests" type="number" value="${l.max_requests}" readonly></label><label>总费用上限（元）<input name="budget_cny" type="number" step="0.000001" value="${escape(l.budget_cny)}" readonly></label><label>最大输出 Token<select name="max_output_tokens"><option value="4096">4096</option></select></label><div id="cost-preview" class="inline-notice"></div><p class="note">官方资格：${escape(s.qualification_status)} · 输入 ${escape(s.input_token_limit)} · 高峰输入 ¥${escape(s.input_cny_per_million)} / 百万、输出 ¥${escape(s.output_cny_per_million)} / 百万。不重试、不换模型。请求上限是整个实测，不是每次点击。</p><label class="consent"><input name="consent" type="checkbox" required><span>我确认将本次已批准的公开源码范围发送至 DeepSeek；最多${l.max_requests}次，保守预约¥${escape(l.budget_cny)}；缺少可靠用量即停止。配置后由我在 Home 点击开始。</span></label><button class="primary" type="submit" ${s.qualification_status!=='VALID'?'disabled':''}>保存本次实测配置</button><button type="button" class="secondary" id="disconnect-model">清除内存凭证</button><p id="settings-message" class="note"></p></form><p class="note">Key：${escape(s.key_status)} · 已保留请求 ${escape(s.reserved_requests??0)} · 停止原因 ${escape(s.stop_reason||'无')}。<a href="#home">返回项目测试 →</a></p>`;}
function settingsPage(){const s=S.settings;if(!s)return empty('正在读取设置','尚未获得本机配置。');const tab=S.settingsTab;
 if(tab==='profile'){ const profile=`<section class="settings-section"><h2>你的本地身份</h2><p class="intro">用于界面显示，不是登录账号，也不授予企业权限。</p><form id="profile-form" class="settings-form"><label>显示名称<input name="display_name" value="${escape(s.profile.display_name)}" maxlength="60" required></label><label>工作区名称<input name="workspace_name" value="${escape(s.profile.workspace_name)}" maxlength="60" required></label><button class="primary" type="submit">保存个人信息</button></form></section>`;return head('个人信息','管理本机显示名称。')+profile;}
 if(tab==='workspace'){ const workspace=`<section class="settings-section"><h2>当前工作区</h2><ul class="fact-list"><li><small>后端启动身份（快照）</small><span class="break-id">${escape(S.meta?.source_identity?.commit)}</span><small>界面 ${Observability.revision}</small></li><li><small>架构基座</small><span class="break-id">${escape(S.meta?.architecture_baseline)}</span></li><li><small>存储 / 范围</small>${escape(S.meta?.backend)} · ${escape(S.meta?.scope_id)}</li><li><small>上下文</small>普通模型对话保存在此工作区。同一会话按输入预算带入近期成功回复；附件和 Wiki 权限单独管理。</li><li><small>权限</small>本机单用户界面；尚无多用户登录、企业 IAM 或正式审批凭证。</li></ul><div class="message-actions"><button class="secondary" id="clear-history">清除下一轮聊天上下文</button></div><p class="note">清除上下文不会删除既有运行、模型收据、费用账本或 R4。资料提取仍是独立 MOCK 流程。</p></section>`;return head('工作区','管理本机上下文。')+workspace;}
 return `${head('设置','连接日常工作使用的模型。')}<section class="settings-section"><h2>模型连接</h2><p role="status">${s.connection_available?'已连接，可以开始工作':'尚未连接模型'}</p><form id="daily-connection-form" class="settings-form"><label>服务商<select name="provider_id"><option value="deepseek">DeepSeek</option></select></label><label>模型<select name="model"><option value="deepseek-flash" ${s.model==='deepseek-flash'?'selected':''}>deepseek-flash（默认）</option><option value="deepseek-v4-pro" ${s.model==='deepseek-v4-pro'?'selected':''}>deepseek-v4-pro（推理模型，单价更高）</option></select></label><label>API Key<input id="api-key" name="api_key" type="password" autocomplete="new-password" spellcheck="false" maxlength="512" ${s.saved_credential_available?'':'required'} placeholder="${s.saved_credential_available?'已在本机保存；留空复用':'输入你的 API Key'}"></label><label class="consent"><input name="remember_key" type="checkbox"><span>在本机安全保存，下次继续使用</span></label><div class="message-actions"><button class="primary" type="submit" ${!s.host_allows_live?'disabled':''}>连接模型</button><button type="button" class="secondary" id="disconnect-model" ${!s.connection_available?'disabled':''}>断开连接</button><button type="button" class="quiet-link" id="forget-credential" ${!s.saved_credential_available?'disabled':''}>删除已保存 Key</button></div><p id="settings-message" class="note" role="status"></p></form><p class="note">${s.saved_credential_available?'Key 已加密保存在本机，不会回显。':'Key 仅用于模型连接。'}连接不会发送模型请求；开发任务会先准备卡片，再由你确认执行。</p></section>`;}
function bindSettings(){
 const daily=$('#daily-connection-form');if(daily)daily.onsubmit=async e=>{e.preventDefault();const f=new FormData(daily),key=daily.elements.api_key;const data={provider_id:f.get('provider_id'),model:f.get('model'),remember:f.get('remember_key')==='on'};if(key.value.trim())data.api_key=key.value.trim();else data.use_saved=true;const button=daily.querySelector('[type="submit"]');button.disabled=true;try{S.settings=await api('/api/settings',{action:'connection',data});key.value='';delete data.api_key;accountMenu();render();toast('模型已连接')}catch(error){key.value='';delete data.api_key;$('#settings-message').textContent='连接未完成：'+error.message;button.disabled=false}};

 document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{S.settingsTab=el.dataset.tab;render()});
 if($('#profile-form'))$('#profile-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{S.settings=await api('/api/settings',{action:'profile',data:{display_name:f.get('display_name'),workspace_name:f.get('workspace_name')}});accountMenu();render();toast('个人信息已保存在本机')}catch(error){toast(error.message)}};
 const model=$('#model-form');if(model){const preview=()=>{const n=Number(model.elements.max_requests.value),o=Number(model.elements.max_output_tokens.value),b=Number(model.elements.budget_cny.value);const s=S.settings;const input=Number(s.input_token_limit),rate=Number(s.input_cny_per_million),output=Number(s.output_cny_per_million);if(s.qualification_status==='BLOCKED'||!Number.isFinite(input)||input<=0||!Number.isFinite(rate)||rate<=0||!Number.isFinite(output)||output<=0){$('#cost-preview').textContent='模型与价格尚未核验，请先更新受信配置。';return;}const one=(input*rate+o*output)/1e6;$('#cost-preview').textContent=`每次保守预约 ¥${one.toFixed(6)}；${n} 次最多预约 ¥${(one*n).toFixed(6)}。达到次数或预算任一上限即停止${b<one?'；当前预算不足一次请求':''}。`};model.oninput=preview;preview();model.onsubmit=async e=>{e.preventDefault();const f=new FormData(model);const key=model.elements.api_key;const payload={provider_id:f.get('provider_id'),model:f.get('model'),api_key:f.get('api_key'),max_requests:Number(f.get('max_requests')),budget_cny:f.get('budget_cny'),max_output_tokens:Number(f.get('max_output_tokens')),consent:f.get('consent')==='on',allow_asset_read:f.get('allow_asset_read')==='on',allow_project_read:f.get('allow_project_read')==='on'};const button=model.querySelector('[type="submit"]');button.disabled=true;try{const action=!payload.api_key&&S.settings.saved_credential_available?'model_saved':f.get('remember_key')==='on'?'model_remember':'model';if(action==='model_saved')delete payload.api_key;S.settings=await api('/api/settings',{action,data:payload});key.value='';payload.api_key='';accountMenu();render();toast(S.projectLiveScope?'实测已配置，尚未调用 API；请回首页点击开始项目理解':'会话已配置，尚未调用 API；可以回首页开始文本测试')}catch(error){key.value='';payload.api_key='';$('#settings-message').textContent='未启用：'+error.message;button.disabled=false}};}
 if($('#save-credential'))$('#save-credential').onclick=async()=>{const key=$('#api-key');try{S.settings=await api('/api/settings',{action:'credential_save',data:{api_key:key.value,confirmed:true}});key.value='';accountMenu();render();toast('已在本机加密保存；没有授权或调用模型')}catch(e){key.value='';toast(e.message)}};
 if($('#forget-credential'))$('#forget-credential').onclick=async()=>{try{S.settings=await api('/api/settings',{action:'credential_forget',data:{confirmed:true}});accountMenu();render();toast('已删除保存凭证；历史账本保留')}catch(e){toast(e.message)}};
 if($('#qualification-check'))$('#qualification-check').onclick=()=>checkQualification();
 if($('#qualification-approve'))$('#qualification-approve').onclick=async e=>{try{S.settings=await api('/api/settings',{action:'qualification_approve',data:{proposal_sha256:e.currentTarget.dataset.sha,confirmed:true}});render()}catch(error){toast(error.message)}};
 if($('#disconnect-model'))$('#disconnect-model').onclick=async()=>{try{S.settings=await api('/api/settings',{action:'disconnect',data:{}});accountMenu();render();toast('凭证已移出当前配置；历史收据保留')}catch(e){toast(e.message)}};
 if($('#clear-history'))$('#clear-history').onclick=async()=>{try{S.settings=await api('/api/settings',{action:'clear_history',data:{}});render();toast('后续聊天上下文已清空；未删除证据')}catch(e){toast(e.message)}};
 if($('#connection-probe'))$('#connection-probe').onclick=()=>{S.files=[];submit('请根据 Catalyst 当前真实已接通的能力，简要介绍你是谁、能做什么、哪些功能尚未开启。')};
}

async function checkQualification(){if(S.qualificationChecking)return;S.qualificationChecking=true;S.qualificationCheckedFor=S.settings?.qualification_sha256;try{const settings=await api('/api/settings',{action:'qualification_check',data:{}});S.settings=settings;if(!$('#api-key')?.value)render();else toast('官方检查已完成；可先安全保存填写的 Key，再查看更新。')}catch(e){toast('官方信息未完成核验，继续保持原门禁：'+e.message)}finally{S.qualificationChecking=false;}}
